+    dst[len * 2] = '\0';
+}
+
+/* Convert hex string to bytes. Returns 0 on success, -1 on failure. */
+static int hex_to_bytes(const char *hex, unsigned char *out, int out_len)
+{
+    int hex_len = (int)strlen(hex);
+    if (hex_len != out_len * 2) return -1;
+    for (int i = 0; i < out_len; ++i) {
+        char a = hex[i * 2];
+        char b = hex[i * 2 + 1];
+        int hi = (a >= '0' && a <= '9') ? a - '0' :
+                 (a >= 'a' && a <= 'f') ? a - 'a' + 10 :
+                 (a >= 'A' && a <= 'F') ? a - 'A' + 10 : -1;
+        int lo = (b >= '0' && b <= '9') ? b - '0' :
+                 (b >= 'a' && b <= 'f') ? b - 'a' + 10 :
+                 (b >= 'A' && b <= 'F') ? b - 'A' + 10 : -1;
+        if (hi < 0 || lo < 0) return -1;
+        out[i] = (unsigned char)((hi << 4) | lo);
+    }
+    return 0;
+}
+
+/* Generate cryptographic random salt. Returns 0 on success. */
+static int generate_salt(unsigned char *salt, int len)
+{
+    if (RAND_bytes(salt, len) != 1) return -1;
+    return 0;
+}
+
+/* Hash password with PBKDF2-HMAC-SHA256. Returns 0 on success. */
+static int hash_password(const char *password,
+                         const unsigned char *salt, int salt_len,
+                         int iterations,
+                         unsigned char *out_hash, int hash_len)
+{
+    if (PKCS5_PBKDF2_HMAC(password, (int)strlen(password),
+                          salt, salt_len,
+                          iterations,
+                          EVP_sha256(),
+                          hash_len, out_hash) != 1) {
+        return -1;
+    }
+    return 0;
+}
+
+/* Constant-time comparison. Returns 1 if equal, 0 otherwise. */
+static int constant_time_eq(const unsigned char *a, const unsigned char *b, int len)
+{
+    unsigned char diff = 0;
+    for (int i = 0; i < len; ++i) diff |= a[i] ^ b[i];
+    return diff == 0;
+}
+
+/* Save a user record: username:salt_hex:iterations:hash_hex\n */
+static int save_user(const char *username,
+                     const unsigned char *salt, int salt_len,
+                     int iterations,
+                     const unsigned char *hash, int hash_len)
+{
+    FILE *f = fopen(USER_DB_PATH, "a");
+    if (!f) return -1;
+
+    char salt_hex[SALT_LEN * 2 + 1];
+    char hash_hex[HASH_LEN * 2 + 1];
+    bytes_to_hex(salt, salt_len, salt_hex);
+    bytes_to_hex(hash, hash_len, hash_hex);
+
+    if (fprintf(f, "%s:%s:%d:%s\n", username, salt_hex, iterations, hash_hex) < 0) {
+        fclose(f);
+        return -1;
+    }
+    fclose(f);
+    return 0;
+}
+
+/* Find user record. Returns 0 on success and fills outputs; -1 if not found or error.
+   Caller-provided buffers must be large enough.
+*/
+static int find_user(const char *username,
+                     unsigned char *out_salt, int salt_len,
+                     int *out_iterations,
+                     unsigned char *out_hash, int hash_len)
+{
+    FILE *f = fopen(USER_DB_PATH, "r");
+    if (!f) {
+        if (errno == ENOENT) return -1; /* DB doesn't exist yet */
+        return -1;
+    }
+
+    char line[LINE_BUF];
+    int found = -1;
+    while (fgets(line, sizeof(line), f)) {
+        /* Trim newline */
+        char *nl = strchr(line, '\n');
+        if (nl) *nl = '\0';
+
+        char name[USERNAME_MAX + 1];
+        char salt_hex[SALT_LEN * 2 + 1];
+        char hash_hex[HASH_LEN * 2 + 1];
+        int iterations = 0;
+
+        if (sscanf(line, "%64[^:]:%32[^:]:%d:%64s", name, salt_hex, &iterations, hash_hex) != 4) {
+            continue; /* skip malformed lines */
+        }
+
+        if (strncmp(name, username, USERNAME_MAX) == 0) {
+            if (hex_to_bytes(salt_hex, out_salt, salt_len) != 0) break;
+            if (hex_to_bytes(hash_hex, out_hash, hash_len) != 0) break;
+            *out_iterations = iterations;
+            found = 0;
+            break;
+        }
+    }
+    fclose(f);
+    return found;
+}
+
+/* Register a new user. Returns 0 on success, -1 on error (e.g., already exists). */
+int register_user(const char *username, const char *password)
+{
+    if (!username || !password) return -1;
+    if (strlen(username) == 0 || strlen(username) > USERNAME_MAX) return -1;
+
+    unsigned char salt[SALT_LEN];
+    unsigned char hash[HASH_LEN];
+
+    /* Check if user exists */
+    unsigned char tmp_salt[SALT_LEN];
+    unsigned char tmp_hash[HASH_LEN];
+    int tmp_iters;
+    if (find_user(username, tmp_salt, SALT_LEN, &tmp_iters, tmp_hash, HASH_LEN) == 0) {
+        /* User already exists */
+        return -1;
+    }
+
+    if (generate_salt(salt, SALT_LEN) != 0) return -1;
+
+    if (hash_password(password, salt, SALT_LEN, DEFAULT_ITERATIONS, hash, HASH_LEN) != 0) return -1;
+
+    if (save_user(username, salt, SALT_LEN, DEFAULT_ITERATIONS, hash, HASH_LEN) != 0) return -1;
+
+    return 0;
+}
+
+/* Authenticate a user. Returns 0 on success (authenticated), -1 on failure. */
+int authenticate_user(const char *username, const char *password)
+{
+    if (!username || !password) return -1;
+
+    unsigned char salt[SALT_LEN];
+    unsigned char stored_hash[HASH_LEN];
+    int iterations = 0;
+
+    if (find_user(username, salt, SALT_LEN, &iterations, stored_hash, HASH_LEN) != 0) {
+        return -1; /* user not found */
+    }
+
+    unsigned char computed_hash[HASH_LEN];
+    if (hash_password(password, salt, SALT_LEN, iterations, computed_hash, HASH_LEN) != 0) {
+        return -1;
+    }
+
+    if (!constant_time_eq(stored_hash, computed_hash, HASH_LEN)) {
+        return -1;
+    }
+
+    return 0;
+}
+
+/* Simple command-line demo: register <user> <pass> | login <user> <pass> */
+int main(int argc, char **argv)
+{
+    if (argc != 4) {
+        fprintf(stderr, "Usage:\n  %s register <username> <password>\n  %s login <username> <password>\n", argv[0], argv[0]);
+        return 1;
+    }
+
+    const char *cmd = argv[1];
+    const char *username = argv[2];
+    const char *password = argv[3];
+
+    if (strcmp(cmd, "register") == 0) {
+        if (register_user(username, password) == 0) {
+            printf("User '%s' registered successfully.\n", username);
+            return 0;
+        } else {
+            fprintf(stderr, "Failed to register user '%s'. It may already exist.\n", username);
+            return 1;
+        }
+    } else if (strcmp(cmd, "login") == 0) {
+        if (authenticate_user(username, password) == 0) {
+            printf("User '%s' authenticated successfully.\n", username);
+            return 0;
+        } else {
+            fprintf(stderr, "Authentication failed for user '%s'.\n", username);
+            return 1;
+        }
+    } else {
+        fprintf(stderr, "Unknown command: %s\n", cmd);
+        return 1;
+    }
+}
